const L = [
 {b:"bibel", t:"Wie die Bibel aufgebaut ist",
  m:"Die Bibel ist eine Bibliothek aus 66 Büchern – aber sie erzählt eine einzige Geschichte: wie Gott Menschen rettet.",
  p:["<b>Altes Testament: 39 Bücher.</b> Gott und sein Volk Israel – die Zeit vor Jesus.","<b>Neues Testament: 27 Bücher.</b> Jesus, die erste Gemeinde und das Leben als Christ.","<b>Rund 40 Schreiber über etwa 1.500 Jahre</b> – Könige, Fischer, ein Arzt, ein Zöllner. Und trotzdem passt alles zusammen.","<b>Die Hauptperson ist Jesus.</b> Er selbst sagt, dass die ganze Schrift von ihm redet."],
  r:["Lukas 24,27","2. Timotheus 3,16","Johannes 5,39"],
  q:"Wie viele Bücher hat die Bibel – und wer ist die Hauptperson?", a:"66 Bücher (39 AT, 27 NT). Die Hauptperson ist Jesus."},
 {b:"bibel", t:"Die Buchgruppen",
  m:"Wenn du weißt, zu welcher Gruppe ein Buch gehört, weißt du sofort, wie du es lesen musst.",
  p:["<b>AT – Gesetz (5):</b> 1.–5. Mose. Schöpfung, Abraham, Auszug aus Ägypten, Gebote.","<b>AT – Geschichte (12):</b> Josua bis Esther. Israel im Land, Könige, Exil.","<b>AT – Weisheit & Lieder (5):</b> Hiob, Psalmen, Sprüche, Prediger, Hoheslied.","<b>AT – Propheten (17):</b> Jesaja bis Maleachi. Gottes Botschaft an sein Volk – und viele Ankündigungen über Jesus.","<b>NT:</b> 4 Evangelien, Apostelgeschichte, 21 Briefe, Offenbarung."],
  r:["Psalm 119,105"],
  q:"Zu welcher Gruppe gehört Hiob?", a:"Zu den Weisheitsbüchern (mit Psalmen, Sprüche, Prediger, Hoheslied)."},
 {b:"bibel", t:"Die große Geschichte in 4 Teilen",
  m:"Schöpfung – Sündenfall – Erlösung – Vollendung. Das ist die ganze Bibel in vier Worten.",
  p:["<b>Schöpfung:</b> Gott macht eine gute Welt und den Menschen nach seinem Bild.","<b>Sündenfall:</b> Der Mensch wendet sich von Gott ab. Damit kommen Schuld, Leid und Tod.","<b>Erlösung:</b> Gott schickt Jesus, der für uns stirbt und aufersteht.","<b>Vollendung:</b> Jesus kommt wieder und macht alles neu – ohne Tränen, Leid und Tod."],
  r:["1. Mose 1,31","1. Mose 3","Johannes 3,16","Offenbarung 21,4–5"],
  q:"Nenne die 4 Teile der großen Geschichte.", a:"Schöpfung, Sündenfall, Erlösung, Vollendung."},
 {b:"bibel", t:"Das Alte Testament kurz erklärt",
  m:"Das AT ist die Geschichte von Gottes Versprechen – und alles läuft auf Jesus zu.",
  p:["<b>Abraham:</b> Gott verspricht ihm, dass durch seine Familie alle Völker gesegnet werden.","<b>Mose:</b> Gott befreit Israel aus Ägypten und gibt die Zehn Gebote.","<b>David:</b> Der große König. Gott verspricht, dass aus seiner Familie ein ewiger König kommt.","<b>Propheten & Exil:</b> Israel verlässt Gott immer wieder. Die Propheten warnen – und kündigen den Retter an."],
  r:["1. Mose 12,3","2. Mose 20","2. Samuel 7,16","Jesaja 9,5"],
  q:"Was hat Gott David versprochen?", a:"Dass aus seiner Familie ein ewiger König kommt – erfüllt in Jesus."},
 {b:"bibel", t:"Das Neue Testament kurz erklärt",
  m:"Evangelien: wer Jesus ist. Apostelgeschichte: wie die Gemeinde startet. Briefe: wie man als Christ lebt. Offenbarung: wie alles endet.",
  p:["<b>4 Evangelien:</b> Leben, Tod und Auferstehung von Jesus aus vier Blickwinkeln.","<b>Apostelgeschichte:</b> Der Heilige Geist kommt, die Gemeinde wächst von Jerusalem bis Rom.","<b>Briefe:</b> Paulus, Petrus, Johannes, Jakobus schreiben an Gemeinden – Glaube im Alltag.","<b>Offenbarung:</b> Jesus siegt. Gott macht alles neu."],
  r:["Johannes 20,31","Apostelgeschichte 1,8"],
  q:"Wovon handelt die Apostelgeschichte?", a:"Wie der Heilige Geist kommt und die erste Gemeinde entsteht und wächst."},
 {b:"bibel", t:"Die 4 Evangelien – der Unterschied",
  m:"Vier Berichte, ein Jesus – jeder zeigt eine andere Seite.",
  p:["<b>Matthäus:</b> Für Juden geschrieben. Jesus ist der versprochene König, viele AT-Erfüllungen.","<b>Markus:</b> Das kürzeste. Schnell, voller Taten. Jesus als der dienende Retter. Super zum Anfangen.","<b>Lukas:</b> Ein Arzt hat genau recherchiert. Jesus für alle – besonders Arme, Frauen, Außenseiter.","<b>Johannes:</b> Ganz anders. Jesus ist Gott. Die „Ich bin“-Worte stehen hier."],
  r:["Lukas 1,1–4","Johannes 20,31"],
  q:"Welches Evangelium ist am kürzesten und gut für Anfänger?", a:"Markus."},
 {b:"bibel", t:"Die Bibel richtig lesen",
  m:"Immer fragen: Wer redet – zu wem – und warum? Ein Vers ohne Zusammenhang kann das Gegenteil bedeuten.",
  p:["<b>Zusammenhang lesen:</b> Mindestens den Abschnitt davor und danach.","<b>Wer redet?</b> In Hiob reden z. B. Freunde, die Gott am Ende korrigiert.","<b>Unklares mit Klarem erklären:</b> Schwierige Stellen im Licht von eindeutigen Stellen verstehen.","<b>Jesus im Zentrum:</b> Alles läuft auf ihn zu."],
  r:["Apostelgeschichte 17,11","2. Timotheus 2,15"],
  q:"Welche drei Fragen stellst du an jeden Bibeltext?", a:"Wer redet? Zu wem? Warum?"},
 {b:"jesus", t:"Wer ist Jesus?",
  m:"Jesus ist ganz Gott und ganz Mensch zugleich.",
  p:["<b>Ganz Gott:</b> Er war von Anfang an bei Gott und ist Gott.","<b>Ganz Mensch:</b> Er wurde geboren, hatte Hunger, war müde, hat geweint.","<b>Ohne Sünde:</b> Als einziger Mensch hat er nie gesündigt.","<b>Darum kann er retten:</b> Als Mensch kann er für Menschen eintreten, als Gott kann er die Schuld tragen."],
  r:["Johannes 1,1","Johannes 1,14","Kolosser 2,9","Hebräer 4,15"],
  q:"Warum musste Jesus Gott und Mensch zugleich sein?", a:"Als Mensch konnte er für Menschen eintreten, als Gott ohne Sünde konnte er die Schuld tragen."},
 {b:"jesus", t:"Vorausgesagt im Alten Testament",
  m:"Hunderte Jahre vorher wurde angekündigt, wo, wie und warum Jesus kommt.",
  p:["<b>Geburtsort Bethlehem:</b> angekündigt in Micha 5,1.","<b>Aus Davids Familie:</b> 2. Samuel 7 und Jesaja 11.","<b>Leiden für fremde Schuld:</b> Jesaja 53 beschreibt das Kreuz Jahrhunderte vorher.","<b>Durchbohrt:</b> Psalm 22 und Sacharja 12,10."],
  r:["Micha 5,1","Jesaja 53,5","Psalm 22","Matthäus 2,5–6"],
  q:"Welches Kapitel im AT beschreibt das Leiden von Jesus besonders deutlich?", a:"Jesaja 53."},
 {b:"jesus", t:"Was Jesus gelehrt und getan hat",
  m:"Jesus hat das Reich Gottes gebracht – mit Worten, Wundern und Liebe für Sünder.",
  p:["<b>Reich Gottes:</b> Gott regiert – und jeder ist eingeladen.","<b>Bergpredigt (Matthäus 5–7):</b> Seine wichtigste Rede. Das Herz zählt, nicht nur äußere Regeln.","<b>Gleichnisse:</b> Geschichten aus dem Alltag, z. B. der verlorene Sohn.","<b>Wunder:</b> Zeichen, wer er ist – Heilungen, Brotvermehrung, Sturmstillung.","<b>Er kam für Sünder:</b> Er suchte die Verlorenen."],
  r:["Markus 1,15","Matthäus 5–7","Lukas 15","Lukas 19,10"],
  q:"Wo steht die Bergpredigt?", a:"Matthäus 5–7."},
 {b:"jesus", t:"Die 7 „Ich bin“-Worte",
  m:"Mit sieben Bildern sagt Jesus im Johannesevangelium, wer er ist.",
  p:["<b>Brot des Lebens</b> – Johannes 6,35","<b>Licht der Welt</b> – Johannes 8,12","<b>Die Tür</b> – Johannes 10,9","<b>Der gute Hirte</b> – Johannes 10,11","<b>Die Auferstehung und das Leben</b> – Johannes 11,25","<b>Der Weg, die Wahrheit und das Leben</b> – Johannes 14,6","<b>Der wahre Weinstock</b> – Johannes 15,5"],
  r:["Johannes 6,35","Johannes 14,6","Johannes 15,5"],
  q:"Nenne mindestens drei „Ich bin“-Worte.", a:"Brot des Lebens, Licht der Welt, Tür, guter Hirte, Auferstehung und Leben, Weg/Wahrheit/Leben, Weinstock."},
 {b:"jesus", t:"Das Kreuz",
  m:"Am Kreuz hat Jesus die Strafe für unsere Schuld getragen – stellvertretend für uns.",
  p:["<b>Stellvertretung:</b> Er starb an unserer Stelle.","<b>„Es ist vollbracht“:</b> Die Schuld ist vollständig bezahlt.","<b>Der Vorhang im Tempel zerriss:</b> Der Weg zu Gott ist offen.","<b>Freiwillig:</b> Niemand hat ihm das Leben genommen – er hat es gegeben."],
  r:["Johannes 19,30","Matthäus 27,51","2. Korinther 5,21","Johannes 10,18"],
  q:"Was bedeutet „Es ist vollbracht“?", a:"Die Schuld ist vollständig bezahlt – es muss nichts mehr dazukommen."},
 {b:"jesus", t:"Auferstehung, Himmelfahrt, Wiederkunft",
  m:"Jesus ist auferstanden, zum Vater gegangen – und er kommt wieder.",
  p:["<b>Auferstehung:</b> Am dritten Tag war das Grab leer. Über 500 Menschen haben ihn gesehen.","<b>Ohne Auferstehung</b> wäre der Glaube sinnlos – mit ihr ist der Tod besiegt.","<b>Himmelfahrt:</b> Nach 40 Tagen ist er zum Vater gegangen.","<b>Wiederkunft:</b> Er kommt sichtbar zurück, richtet und macht alles neu."],
  r:["1. Korinther 15,3–6","1. Korinther 15,14","Apostelgeschichte 1,9–11"],
  q:"Wie viele Menschen haben den Auferstandenen laut Paulus gesehen?", a:"Über 500 (1. Korinther 15,6)."},
 {b:"evang", t:"Das Evangelium in 4 Worten",
  m:"Gott – Mensch – Jesus – Antwort. Damit kannst du jedem das Evangelium erklären.",
  p:["<b>Gott:</b> Er ist heilig und liebt uns.","<b>Mensch:</b> Wir haben gesündigt und sind von Gott getrennt.","<b>Jesus:</b> Er ist für uns gestorben und auferstanden.","<b>Antwort:</b> Umkehren und Jesus vertrauen."],
  r:["Römer 3,23","Römer 6,23","Römer 5,8","Römer 10,9"],
  q:"Wie heißen die 4 Worte des Evangeliums?", a:"Gott – Mensch – Jesus – Antwort."},
 {b:"evang", t:"Was ist Sünde?",
  m:"Sünde heißt: das Ziel verfehlen. Ohne Gott leben und gegen seinen Willen handeln.",
  p:["<b>Nicht nur Taten:</b> Auch Gedanken, Worte und das Gute, das wir nicht tun.","<b>Alle sind betroffen:</b> Keiner ist gerecht.","<b>Ein Gebot gebrochen = schuldig am ganzen Gesetz.</b>","<b>Die Folge:</b> Trennung von Gott und am Ende der Tod."],
  r:["Römer 3,23","Jakobus 2,10","Römer 6,23","Jesaja 59,2"],
  q:"Was bedeutet das Wort Sünde ursprünglich?", a:"Das Ziel verfehlen."},
 {b:"evang", t:"Gnade",
  m:"Gnade heißt: Gott schenkt dir, was du nicht verdient hast.",
  p:["<b>Unverdient:</b> Nicht durch Leistung, nicht durch gute Taten.","<b>Geschenk:</b> Man kann es nur annehmen.","<b>Keiner kann sich rühmen.</b>","<b>Gnade verändert:</b> Wer sie erlebt, will anders leben – nicht um sich etwas zu verdienen, sondern aus Dank."],
  r:["Epheser 2,8–9","Titus 3,5","Römer 6,23"],
  q:"Was ist der Unterschied zwischen Lohn und Gnade?", a:"Lohn verdient man, Gnade ist ein unverdientes Geschenk."},
 {b:"evang", t:"Umkehr und Glaube",
  m:"Umkehren heißt: weg von der Sünde, hin zu Gott. Glauben heißt: Jesus vertrauen.",
  p:["<b>Umkehr (Buße):</b> Ehrlich werden, Schuld bekennen, die Richtung ändern.","<b>Glaube:</b> Nicht nur „für wahr halten“, sondern Jesus das Leben anvertrauen.","<b>Bekennen und glauben:</b> mit dem Mund bekennen, im Herzen glauben.","<b>Gott vergibt:</b> treu und gerecht."],
  r:["Markus 1,15","Apostelgeschichte 3,19","Römer 10,9–10","1. Johannes 1,9"],
  q:"Was ist mehr als nur „für wahr halten“?", a:"Echter Glaube: Jesus das eigene Leben anvertrauen."},
 {b:"evang", t:"Neues Leben und Gewissheit",
  m:"Wer zu Jesus gehört, ist ein neuer Mensch – und darf sicher wissen, dass er ewiges Leben hat.",
  p:["<b>Neue Kreatur:</b> Das Alte ist vergangen.","<b>Gottes Kind:</b> Wer Jesus aufnimmt, wird Kind Gottes.","<b>Gewissheit:</b> Sie hängt an Gottes Versprechen, nicht am Gefühl.","<b>Niemand reißt dich aus seiner Hand.</b>"],
  r:["2. Korinther 5,17","Johannes 1,12","1. Johannes 5,13","Johannes 10,28"],
  q:"Woran hängt die Heilsgewissheit – am Gefühl oder an etwas anderem?", a:"An Gottes Versprechen, nicht am Gefühl."},
 {b:"glaube", t:"Wer ist Gott?",
  m:"Gott ist heilig, gerecht und Liebe – und er will Beziehung mit dir.",
  p:["<b>Heilig:</b> Völlig rein, ohne jedes Böse.","<b>Gerecht:</b> Ihm ist Unrecht nicht egal.","<b>Liebe:</b> Nicht nur liebevoll – er ist Liebe.","<b>Allmächtig, allwissend, überall:</b> Nichts ist ihm unmöglich oder verborgen.","<b>Ewig und treu:</b> Er ändert sich nicht."],
  r:["Jesaja 6,3","1. Johannes 4,8","Psalm 139","Maleachi 3,6"],
  q:"Nenne drei Eigenschaften Gottes.", a:"Z. B. heilig, gerecht, Liebe, allmächtig, allwissend, ewig, treu."},
 {b:"glaube", t:"Die Dreieinigkeit",
  m:"Ein Gott in drei Personen: Vater, Sohn und Heiliger Geist.",
  p:["<b>Es gibt nur einen Gott.</b>","<b>Drei Personen:</b> Vater, Sohn (Jesus) und Heiliger Geist – alle drei sind Gott.","<b>Zusammen in einem Vers:</b> Taufe auf den Namen des Vaters, des Sohnes und des Heiligen Geistes.","<b>Ehrlich:</b> Kein Vergleich passt perfekt. Gott ist größer als unser Verstand."],
  r:["5. Mose 6,4","Matthäus 28,19","Matthäus 3,16–17"],
  q:"Bei welchem Ereignis sind Vater, Sohn und Geist gleichzeitig zu sehen und zu hören?", a:"Bei der Taufe von Jesus (Matthäus 3,16–17)."},
 {b:"glaube", t:"Der Heilige Geist",
  m:"Der Heilige Geist ist Gott, der in jedem Christen wohnt.",
  p:["<b>Eine Person, keine Kraft:</b> Er lehrt, tröstet, führt.","<b>Er wohnt in dir:</b> Dein Leib ist sein Tempel.","<b>Er verändert:</b> Frucht des Geistes – Liebe, Freude, Friede, Geduld …","<b>Er gibt Kraft</b>, Zeuge für Jesus zu sein."],
  r:["Johannes 14,26","1. Korinther 6,19","Galater 5,22–23","Apostelgeschichte 1,8"],
  q:"Nenne drei Teile der Frucht des Geistes.", a:"Liebe, Freude, Friede, Geduld, Freundlichkeit, Güte, Treue, Sanftmut, Selbstbeherrschung."},
 {b:"glaube", t:"Gebet",
  m:"Gebet ist Reden mit Gott – wie ein Kind mit seinem Vater.",
  p:["<b>Das Vaterunser als Muster:</b> Gott ehren – sein Wille – tägliches Brot – Vergebung – Schutz.","<b>Ehrlich sein:</b> Auch Zweifel und Klagen dürfen rein (siehe Psalmen).","<b>Ohne Unterlass:</b> Gebet ist eine Haltung, nicht nur eine Uhrzeit.","<b>Der Geist hilft</b>, wenn wir nicht wissen, was wir beten sollen."],
  r:["Matthäus 6,9–13","Philipper 4,6–7","1. Thessalonicher 5,17","Römer 8,26"],
  q:"Welches Gebet hat Jesus als Muster gegeben?", a:"Das Vaterunser (Matthäus 6,9–13)."},
 {b:"glaube", t:"Gemeinde, Taufe, Abendmahl",
  m:"Christsein ist kein Einzelsport. Gott hat uns in eine Familie gestellt.",
  p:["<b>Gemeinde:</b> Der Leib Christi – jeder hat seinen Platz und seine Gaben.","<b>Taufe:</b> Öffentliches Bekenntnis: Ich gehöre zu Jesus.","<b>Abendmahl:</b> Erinnerung an das Kreuz und Gemeinschaft mit Jesus.","<b>Treffen nicht verlassen:</b> Wir brauchen einander."],
  r:["1. Korinther 12,27","Apostelgeschichte 2,38","1. Korinther 11,23–26","Hebräer 10,25"],
  q:"Woran erinnert das Abendmahl?", a:"An den Tod von Jesus am Kreuz für uns."},
 {b:"glaube", t:"Tod, Gericht und Ewigkeit",
  m:"Jeder Mensch steht einmal vor Gott. Für Christen ist der Tod nicht das Ende, sondern der Anfang.",
  p:["<b>Einmal sterben, danach das Gericht.</b>","<b>Wer an Jesus glaubt,</b> ist schon vom Tod ins Leben übergegangen.","<b>Himmel:</b> Für immer bei Gott – ohne Tränen und Leid.","<b>Neue Erde:</b> Gott macht am Ende alles neu."],
  r:["Hebräer 9,27","Johannes 5,24","Offenbarung 21,1–4"],
  q:"Was sagt Johannes 5,24 über Glaubende?", a:"Sie sind schon vom Tod ins Leben übergegangen."},
 {b:"seel", t:"Die Haltung des Seelsorgers",
  m:"Nicht ich bin der Ratgeber – Jesus ist es. Ich höre zu und bringe Gottes Wort.",
  p:["<b>Zuhören:</b> Schnell zum Hören, langsam zum Reden.","<b>Demut:</b> Nicht erhöhen, nicht überreden.","<b>Kein Druck:</b> Klarstellen, dass es kein Muss gibt.","<b>Bibel statt Meinung.</b>"],
  r:["Jesaja 9,5","Jakobus 1,19","Galater 6,1–2","1. Petrus 3,15"],
  q:"Wer ist der eigentliche Ratgeber in der Seelsorge?", a:"Jesus – der „Wunder-Rat“ (Jesaja 9,5)."},
 {b:"seel", t:"Die drei Arten von Menschen",
  m:"Erst erkennen, wer vor dir steht – dann weißt du, was er braucht.",
  p:["<b>Bekehrt:</b> braucht Aufbau, Stütze, Ermutigung.","<b>Unbekehrt:</b> braucht Jesus und die frohe Botschaft.","<b>Nur scheinbar bekehrt:</b> meint, es aus eigener Kraft geschafft zu haben – braucht sanfte Selbstprüfung (Matthäus 7,21–23)."],
  r:["1. Thessalonicher 5,11","Johannes 3,16","2. Korinther 13,5"],
  q:"Was braucht jemand, der nur scheinbar bekehrt ist?", a:"Eine sanfte, ehrliche Selbstprüfung."},
 {b:"seel", t:"Das Evangelium im Gespräch",
  m:"Mit vier Versen aus dem Römerbrief kannst du das ganze Evangelium erklären.",
  p:["<b>Römer 3,23:</b> Alle haben gesündigt.","<b>Römer 6,23:</b> Die Folge ist der Tod – aber Gott schenkt ewiges Leben.","<b>Römer 5,8:</b> Christus starb für uns, als wir noch Sünder waren.","<b>Römer 10,9–10:</b> Bekennen und glauben – gerettet.","<b>Tipp:</b> Schreib in deiner Bibel neben jeden Vers den nächsten („→ Röm 6,23“)."],
  r:["Römer 3,23","Römer 6,23","Römer 5,8","Römer 10,9–10"],
  q:"Nenne die 4 Verse des Römer-Wegs in der richtigen Reihenfolge.", a:"Römer 3,23 → 6,23 → 5,8 → 10,9–10."},
 {b:"seel", t:"Grenzen kennen",
  m:"Bei schweren Fällen nicht allein weitermachen – einen älteren, erfahrenen Bruder dazuholen.",
  p:["<b>Schwere Fälle:</b> Suizidgedanken, Gewalt, Sucht, große seelische Not.","<b>Wo viele Ratgeber sind, findet sich Hilfe.</b>","<b>Vertrauen schützen:</b> Persönliches nicht weitererzählen.","<b>Selbst versorgt bleiben:</b> Auch der Seelsorger braucht Gebet und Begleitung."],
  r:["Sprüche 11,14","Sprüche 11,13","Galater 6,2"],
  q:"Was tust du bei einem schweren Fall?", a:"Nicht allein weitermachen, sondern einen erfahrenen Bruder dazuholen."},
 {b:"rede", t:"Der Aufbau einer Einleitung",
  m:"Einstieg – Spiegel – Wendepunkt – Hoffnung – Überleitung. Fünf Teile, fünf Minuten.",
  p:["<b>Einstieg:</b> Ein Bild oder eine Frage, die jeder kennt.","<b>Spiegel:</b> 2–3 Fragen mit Pausen. Hier entsteht Bewegung.","<b>Wendepunkt:</b> „Ich stehe hier mittendrin.“ Dich selbst einschließen.","<b>Hoffnung:</b> Was Gott verspricht.","<b>Überleitung:</b> „Lasst uns hören, was Gott uns sagen will.“"],
  r:["Kolosser 4,6"],
  q:"Wie heißen die 5 Teile einer Einleitung?", a:"Einstieg, Spiegel, Wendepunkt, Hoffnung, Überleitung."},
 {b:"rede", t:"Gute Vergleiche und Pausen",
  m:"Ein gutes Bild bleibt länger hängen als zehn gute Sätze. Und eine Pause wirkt stärker als jedes Wort.",
  p:["<b>Bilder aus dem Alltag:</b> Tanken, Haus auf Sand, Auge des Sturms.","<b>Ein Bild pro Einleitung</b> – und es später nochmal aufgreifen.","<b>Pausen aushalten:</b> Nach Fragen 3–5 Sekunden still sein.","<b>Laut üben:</b> Zwei-, dreimal vorher, dann frei sprechen."],
  r:["Matthäus 13,34"],
  q:"Wie lange solltest du nach einer Frage still sein?", a:"Etwa 3–5 Sekunden – die Pause aushalten."}
];
const ROUTINE = [{id:"still", ic:"🙏", n:"Stille Zeit"},{id:"lern", ic:"🧠", n:"1 Lektion"},{id:"geben", ic:"💬", n:"Weitergeben"}];
const BOOKS = {GEN:"1. Mose",EXO:"2. Mose",LEV:"3. Mose",NUM:"4. Mose",DEU:"5. Mose",JOS:"Josua",JDG:"Richter",RUT:"Rut","1SA":"1. Samuel","2SA":"2. Samuel","1KI":"1. Könige","2KI":"2. Könige",NEH:"Nehemia",EST:"Ester",JOB:"Hiob",PSA:"Psalm",PRO:"Sprüche",ECC:"Prediger",ISA:"Jesaja",JER:"Jeremia",EZK:"Hesekiel",DAN:"Daniel",JON:"Jona",MIC:"Micha",ZEC:"Sacharja",MAL:"Maleachi",MAT:"Matthäus",MRK:"Markus",LUK:"Lukas",JHN:"Johannes",ACT:"Apostelgeschichte",ROM:"Römer","1CO":"1. Korinther","2CO":"2. Korinther",GAL:"Galater",EPH:"Epheser",PHP:"Philipper",COL:"Kolosser","1TH":"1. Thessalonicher","2TI":"2. Timotheus",TIT:"Titus",HEB:"Hebräer",JAS:"Jakobus","1PE":"1. Petrus","1JN":"1. Johannes",REV:"Offenbarung"};
const CODE = Object.fromEntries(Object.entries(BOOKS).map(([k,v]) => [v,k]));
const BIBLE = "https://www.bible.com/de/bible/73/";
const segText = (s, withBook) => { const [b,c,v] = s.split("."); return (withBook ? BOOKS[b] + " " : "") + c + (v ? "," + v.replace("-", "–") : ""); };
function refText(list){ let out = "", last = ""; list.forEach((s,i) => { const b = s.split(".")[0]; out += (i ? " · " : "") + segText(s, b !== last); last = b; }); return out; }
function refUrl(r){
  const m = r.match(/^(.+?)\s+(\d+)(?:,(\d+))?(?:[–-](\d+))?(?:,(\d+))?$/);
  if (!m || !CODE[m[1]]) return "https://www.bible.com/de/search/bible?q=" + encodeURIComponent(r);
  const [, book, c, v1, x, v2] = m, code = CODE[book];
  if (!v1) return BIBLE + code + "." + c + ".HFA";
  if (v2) return BIBLE + code + "." + c + "." + v1 + ".HFA";
  return BIBLE + code + "." + c + "." + v1 + (x ? "-" + x : "") + ".HFA";
}
